Add-Type -AssemblyName System.Drawing
$out = Split-Path -Parent $MyInvocation.MyCommand.Path
$content = Get-Content -Raw -Encoding UTF8 (Join-Path $out 'korean-architecture-content.json') | ConvertFrom-Json
$font = New-Object System.Drawing.Font('Malgun Gothic', 12); $small = New-Object System.Drawing.Font('Malgun Gothic', 10); $label = New-Object System.Drawing.Font('Malgun Gothic', 14, [System.Drawing.FontStyle]::Bold); $title = New-Object System.Drawing.Font('Malgun Gothic', 27, [System.Drawing.FontStyle]::Bold)
$white = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White); $ink = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(20,30,45))
$green = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(232,247,235)); $green2 = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(28,112,54), 2)
$orange = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255,243,229)); $orange2 = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(222,92,19), 2)
$blue = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(235,242,255)); $blue2 = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(38,80,190), 2)
$purple = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(244,238,255)); $purple2 = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(88,43,180), 2)
$gray = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(248,250,252)); $gray2 = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(90,105,125), 2); $line = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(55,65,81), 2)
function Box($g,$x,$y,$w,$h,$item,$fill,$stroke){$g.FillRectangle($fill,$x,$y,$w,$h);$g.DrawRectangle($stroke,$x,$y,$w,$h);$sf=[System.Drawing.StringFormat]::new();$sf.Alignment='Center';$sf.LineAlignment='Near';$g.DrawString($item.head,$label,$ink,[System.Drawing.RectangleF]::new($x+8,$y+10,$w-16,32),$sf);$g.DrawString($item.body,$small,$ink,[System.Drawing.RectangleF]::new($x+14,$y+50,$w-28,$h-58),$sf)}
function Arrow($g,$x1,$y1,$x2,$y2,$text=''){$g.DrawLine($line,$x1,$y1,$x2,$y2);$g.FillPolygon($ink,@([System.Drawing.Point]::new($x2,$y2),[System.Drawing.Point]::new($x2-10,$y2-5),[System.Drawing.Point]::new($x2-10,$y2+5)));if($text){$sf=[System.Drawing.StringFormat]::new();$sf.Alignment='Center';$g.DrawString($text,$small,$ink,[System.Drawing.RectangleF]::new(($x1+$x2)/2-70,($y1+$y2)/2-20,140,38),$sf)}}
$w=2600;$h=1700;$b=New-Object System.Drawing.Bitmap($w,$h);$g=[System.Drawing.Graphics]::FromImage($b);$g.Clear([System.Drawing.Color]::White);$g.SmoothingMode='AntiAlias'
$g.DrawString($content.title,$title,$ink,440,24);$g.DrawString($content.subtitle,$font,$ink,890,70)
Box $g 35 270 260 330 $content.user $gray $gray2;Box $g 335 270 270 330 $content.frontend $green $green2;Arrow $g 295 430 335 430 'input'
$g.DrawRectangle($green2,650,125,820,1230);$g.DrawString('Main API Server - Node.js HTTP Server',$label,$ink,870,145)
Box $g 690 200 740 140 $content.routes $gray $green2;Box $g 690 370 740 145 $content.validation $green $green2;Box $g 690 545 740 175 $content.orchestrator $green $green2;Arrow $g 1060 340 1060 370 'request';Arrow $g 1060 515 1060 545 'validated'
Box $g 690 770 350 220 $content.knowledge $blue $blue2;Box $g 1080 770 350 220 $content.data $blue $blue2;Arrow $g 860 720 860 770 'lookup';Arrow $g 1040 880 1080 880 'read'
Box $g 690 1030 350 220 $content.agents $orange $orange2;Box $g 1080 1030 350 220 $content.model $orange $orange2;Arrow $g 1210 720 1210 1030 'generate';Arrow $g 1040 1140 1080 1140 'call'
Box $g 1520 140 420 205 $content.cat $blue $blue2;Box $g 1520 385 420 205 $content.video $gray $gray2;Box $g 1520 630 420 205 $content.development $gray $gray2;Box $g 1520 875 420 205 $content.workmate $gray $gray2;Arrow $g 1470 615 1520 240 'Cat';Arrow $g 1470 735 1520 485 'Video';Arrow $g 1470 870 1520 730 'Dev';Arrow $g 1470 1050 1520 975 'Work'
Box $g 1990 140 400 300 $content.a2a $purple $purple2;Box $g 1990 505 400 300 $content.ops $purple $purple2;Box $g 1990 870 400 300 $content.response $green $green2;Arrow $g 1940 240 1990 240 'external';Arrow $g 1940 1030 1990 1030 'merge';Arrow $g 1430 1200 1990 655 'ops data'
$g.DrawRectangle($blue2,35,1390,2355,230);$g.DrawString('End-to-end flow',$label,$ink,75,1410);$x=100;for($i=0;$i -lt $content.flow.Count;$i++){ $g.FillEllipse($blue,[System.Drawing.Rectangle]::new($x,1490,54,54));$g.DrawString(($i+1).ToString(),$label,$ink,$x+18,1498);$g.DrawString($content.flow[$i],$font,$ink,$x-20,1555);if($i -lt 5){Arrow $g ($x+60) 1517 ($x+260) 1517};$x+=400 }
$path=Join-Path $out 'game-qna-api-detailed-architecture-ko.png';$g.Dispose();$b.Save($path,[System.Drawing.Imaging.ImageFormat]::Png);$b.Dispose();Write-Output $path
